import { useState } from "react";
//#region src/usePrevious/index.ts
function usePrevious(value) {
	const [current, setCurrent] = useState(value);
	const [previous, setPrevious] = useState();
	if (value !== current) {
		setPrevious(current);
		setCurrent(value);
	}
	return previous;
}
//#endregion
export { usePrevious };
